137	async fn diagnostic_retained_records(file : @fs.File, size : Int64) -> String {
138	  let length = if size > 262144L { 262144 } else { size.to_int() }
139	  let bytes = FixedArray::make(length, b'\x00')
140	  let read = file.read_at(bytes, position=size - length.to_int64())
141	  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
142	  let lines = text.split("\n").to_array()
143	  let kept = FixedArray::make(lines.length(), false)
144	  let mut remaining = 65536
145	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
146	    if i == 0 && size > length.to_int64() {
147	      continue
148	    }
149	    let length = lines[i].length() + 1
150	    if length <= remaining {
151	      kept[i] = true
152	      remaining -= length
153	    }
154	  }
155	  remaining = 65536
156	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
157	    if kept[i] || (i == 0 && size > length.to_int64()) {
158	      continue
159	    }
160	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
161	    let failed = field(event, "errorType") is Some(_) ||
162	      (match field(event, "status") {
163	        Some(Json::String(status)) =>
164	          ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
165	            status,
166	          )
167	        _ => false
168	      })
169	    let length = lines[i].length() + 1
170	    if failed && length <= remaining {
171	      kept[i] = true
172	      remaining -= length
173	    }
174	  }
175	  let result = @buffer.Buffer(size_hint=131072)
176	  for i in 0..<lines.length() {
177	    if kept[i] {
178	      result.write_string_utf8(lines[i].to_owned() + "\n")
179	    }
180	  }
181	  @utf8.decode_lossy(result.to_bytes())
182	}
