+///|
+fn redact_known_values(
+  text : String,
+  secrets : Array[String],
+  short_values : Array[String],
+) -> String {
+  let chars = text.iter().to_array()
+  let values : Array[(Array[Char], Bool)] = []
+  for secret in secrets {
+    if secret.length() <= text.length() {
+      values.push((secret.iter().to_array(), false))
+    }
+  }
+  for value in short_values {
+    if value.length() <= text.length() {
+      values.push((value.iter().to_array(), true))
+    }
+  }
+  let result = @buffer.Buffer(size_hint=text.length())
+  let mut i = 0
+  while i < chars.length() {
+    let mut matched = 0
+    for index in 0..<values.length() {
+      let (value, boundary_only) = values[index]
+      let mut matches = value.length() > 0 &&
+        i + value.length() <= chars.length()
+      if matches {
+        for j in 0..<value.length() {
+          if chars[i + j] != value[j] {
+            matches = false
+            break
+          }
+        }
+      }
+      if matches &&
+        (
+          !boundary_only ||
+          (
+            (i == 0 || !credential_word(chars[i - 1])) &&
+            (
+              i + value.length() == chars.length() ||
+              !credential_word(chars[i + value.length()])
+            )
+          )
+        ) {
+        matched = value.length()
+        break
+      }
+    }
+    if matched > 0 {
+      result.write_string_utf8("[redacted]")
+      i += matched
+    } else {
+      result.write_char_utf8(chars[i])
+      i += 1
+    }
+  }
+  @utf8.decode_lossy(result.to_bytes())
+}
