607	  progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
608	  let lines = []
609	  let mut incomplete = omitted
610	  let source_lines = message.split("\n").to_array()
611	  for index in 0..<source_lines.length() {
612	    let line = source_lines[index]
613	    if lines.length() == 32 {
614	      incomplete = true
615	      ignore(lines.remove(1))
616	    }
617	    let truncated = line.length() > 1024
618	    let bounded = if truncated {
619	      incomplete = true
