621	    } else {
622	      line.to_owned()
623	    }
624	    let bounded = if truncated ||
625	      (incomplete_final_line && index == source_lines.length() - 1) {
626	      diagnostic_partial_secret(
627	        bounded,
628	        progress.secrets + progress.short_values,
629	      )
630	    } else {
631	      bounded
632	    }
