648	///|
649	fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
650	  let chars = text.iter().to_array()
651	  let mut boundary = chars.length()
652	  for secret in secrets {
653	    let value = secret.iter().to_array()
654	    if value.length() == 0 || text.has_suffix(secret) {
655	      continue
656	    }
657	    let limit = if value.length() - 1 < boundary {
658	      value.length() - 1
659	    } else {
660	      boundary
661	    }
662	    if limit == 0 {
663	      continue
664	    }
665	    let prefixes = FixedArray::make(limit, 0)
666	    let mut matched = 0
667	    for index in 1..<limit {
668	      while matched > 0 && value[matched] != value[index] {
669	        matched = prefixes[matched - 1]
670	      }
671	      if value[matched] == value[index] {
672	        matched += 1
673	      }
674	      prefixes[index] = matched
675	    }
676	    matched = 0
677	    for index in 0..<boundary {
678	      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
679	        matched = prefixes[matched - 1]
680	      }
681	      if matched < limit && value[matched] == chars[index] {
682	        matched += 1
683	      }
684	    }
685	    boundary -= matched
686	  }
687	  if boundary == chars.length() {
688	    text
689	  } else {
690	    character_text(chars, 0, boundary) + "[redacted]"
691	  }
692	}
