294	fn classic_build_step(text : String) -> Bool {
295	  guard text.has_prefix("Step ") &&
296	    text[5:].split_once("/") is Some((step, rest)) &&
297	    rest.split_once(" ") is Some((total, detail)) else {
298	    return false
299	  }
300	  step.length() > 0 &&
301	  total.length() > 0 &&
302	  step.iter().all(c => c >= '0' && c <= '9') &&
303	  total.iter().all(c => c >= '0' && c <= '9') &&
304	  detail.trim().has_prefix(":")
305	}
