 43	///|
 44	fn character_text(chars : Array[Char], start : Int32, end : Int32) -> String {
 45	  let buffer = @buffer.Buffer(size_hint=end - start)
 46	  for i in start..<end {
 47	    buffer.write_char_utf8(chars[i])
 48	  }
 49	  @utf8.decode_lossy(buffer.to_bytes())
 50	}
 51	
 52	///|
 53	fn credential_hex(c : Char) -> Int32? {
 54	  match c {
 55	    '0'..<='9' => Some(c.to_int() - '0'.to_int())
 56	    'a'..<='f' => Some(c.to_int() - 'a'.to_int() + 10)
 57	    'A'..<='F' => Some(c.to_int() - 'A'.to_int() + 10)
 58	    _ => None
 59	  }
 60	}
