 62	///|
 63	fn credential_parameter(name : String) -> String {
 64	  let chars = name.iter().to_array()
 65	  let buffer = @buffer.Buffer(size_hint=name.length())
 66	  let mut i = 0
 67	  while i < chars.length() {
 68	    if chars[i] == '%' &&
 69	      i + 2 < chars.length() &&
 70	      credential_hex(chars[i + 1]) is Some(hi) &&
 71	      credential_hex(chars[i + 2]) is Some(lo) {
 72	      buffer.write_char_utf8((hi * 16 + lo).unsafe_to_char())
 73	      i += 3
 74	    } else {
 75	      buffer.write_char_utf8(chars[i])
 76	      i += 1
 77	    }
 78	  }
 79	  @utf8.decode_lossy(buffer.to_bytes())
 80	}
