192	          ['"', '\''].contains(chars[start - 1]) &&
193	          chars[start - 1] == chars[end]
194	        if ["cookie", "set-cookie", "--cookie"].contains(lower) && !quoted_key {
195	          buffer.write_string_utf8("[redacted]")
196	          i = chars.length()
197	        } else if value + 10 <= chars.length() &&
198	          character_text(chars, value, value + 10) == "[redacted]" {
