200	          i = value + 10
201	        } else if value < chars.length() && ['"', '\''].contains(chars[value]) {
202	          let quote = chars[value]
203	          buffer.write_char_utf8(quote)
204	          value += 1
205	          while value < chars.length() && chars[value] != quote {
206	            if chars[value] == '\\' && value + 1 < chars.length() {
207	              value += 1
208	            }
209	            value += 1
210	          }
211	          buffer.write_string_utf8("[redacted]")
212	          i = value
213	        } else {
214	          let mut value_end = value
215	          while value_end < chars.length() && !credential_end(chars[value_end]) {
216	            value_end += 1
217	          }
218	          let scheme = character_text(chars, value, value_end).to_lower()
219	          if scheme == "bearer" || scheme == "basic" {
220	            while value_end < chars.length() &&
221	                  credential_space(chars[value_end]) {
