278	///|
279	fn redact_known_values(
280	  text : String,
281	  secrets : Array[String],
282	  short_values : Array[String],
283	) -> String {
284	  let chars = text.iter().to_array()
285	  let values : Array[(Array[Char], Bool)] = []
286	  for secret in secrets {
287	    if secret.length() <= text.length() {
288	      values.push((secret.iter().to_array(), false))
289	    }
290	  }
291	  for value in short_values {
292	    if value.length() <= text.length() {
293	      values.push((value.iter().to_array(), true))
294	    }
295	  }
296	  let result = @buffer.Buffer(size_hint=text.length())
297	  let mut i = 0
298	  while i < chars.length() {
299	    let mut matched = 0
300	    for index in 0..<values.length() {
301	      let (value, boundary_only) = values[index]
302	      let mut matches = value.length() > 0 &&
303	        i + value.length() <= chars.length()
304	      if matches {
305	        for j in 0..<value.length() {
306	          if chars[i + j] != value[j] {
307	            matches = false
308	            break
309	          }
310	        }
311	      }
312	      if matches &&
313	        (
314	          !boundary_only ||
315	          (
316	            (i == 0 || !credential_word(chars[i - 1])) &&
317	            (
318	              i + value.length() == chars.length() ||
319	              !credential_word(chars[i + value.length()])
320	            )
321	          )
322	        ) {
323	        matched = value.length()
324	        break
325	      }
326	    }
327	    if matched > 0 {
328	      result.write_string_utf8("[redacted]")
329	      i += matched
330	    } else {
331	      result.write_char_utf8(chars[i])
332	      i += 1
333	    }
334	  }
335	  @utf8.decode_lossy(result.to_bytes())
336	}

