 44	async fn observe_activity(state : Json) -> Json {
 45	  let directory = required(state, "tunnelDirectory")
 46	  let pairing = if @fs.exists(directory + "/pairing-code") {
 47	    @fs.read_file(directory + "/pairing-code").text()
 48	  } else {
 49	    ""
 50	  }
 51	  let script = activity_command(state)
 52	  let (input, writer) = @process.write_to_process()
 53	  defer writer.close()
 54	  let (output, reader) = @process.read_from_process()
 55	  defer output.close()
 56	  let (errors, stderr) = @process.read_from_process()
 57	  defer errors.close()
 58	  let progress = Progress::new(
 59	    "activity-probe",
 60	    environment=workspace_environment(state),
 61	    recording_override=state_recording(state),
 62	  )
 63	  if pairing != "" {
 64	    progress.secrets.push(pairing)
 65	    for line in pairing.split("\n") {
 66	      if line.trim() != "" && line.length() < pairing.length() {
 67	        progress.secrets.push(line.to_owned())
 68	      }
 69	    }
 70	    progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
 71	  }
 72	  let mut phase = "master"
 73	  let mut exit_code = None
 74	  let mut failure_codes : Array[Json] = []
 75	  errdefer save_diagnostic(
 76	    "activity-probe",
 77	    "failed",
 78	    error_type="observation_failed",
 79	    phase~,
 80	    exit_code?,
 81	    evidence={ "errors": Json::array(failure_codes) },
 82	    error_message=progress.failure_detail(),
 83	    details_truncated=progress.details_truncated,
 84	    tunnel_directory=directory,
 85	    recording=state_recording(state),
 86	    environment=workspace_environment(state),
 87	    protected_secrets=[pairing],
 88	  )
 89	  @async.with_timeout(30000, async fn() {
 90	    let args = mux_ssh_args(state)
 91	    phase = "spawn"
 92	    @async.with_task_group(async fn(group) {
 93	      let child = @process.spawn(
 94	        group,
 95	        workspace_program(state, "ssh"),
 96	        extra_env=workspace_environment(state),
 97	        inherit_env=false,
 98	        cwd?=workspace_directory(state).map(path => path[:]),
 99	        args + [script],
100	        stdin=input,
101	        stdout=reader,
102	        stderr~,
103	      )
104	      let collected_errors = group.spawn(async fn() {
105	        ignore(progress.read_output(errors, capture=false))
106	      })
107	      let reading = group.spawn(async fn() {
108	        let buffer = @buffer.Buffer()
109	        let bytes = FixedArray::make(4096, b'\x00')
110	        while true {
111	          let count = output.read(bytes)
112	          if count == 0 {
113	            break
114	          }
115	          guard buffer.length() + count <= 4194304 else {
116	            raise AdapterError("Activity response too large")
117	          }
118	          buffer.write_bytes(Bytes::from_array(bytes[:count].to_owned()))
119	        }
120	        @utf8.decode(buffer.to_bytes())
121	      })
122	      let payload : Json = { "pairingCode": pairing }
123	      writer.write(payload.stringify())
124	      writer.close()
125	      phase = "result"
126	      let code = child.wait()
127	      exit_code = Some(code)
128	      collected_errors.wait()
129	      phase = "schema"
130	      let raw = reading.wait()
131	      let parsed = Some(@json.parse(raw)) catch { _ => None }
132	      if parsed is Some(value) &&
133	        field(value, "errors") is Some(Json::Array(errors)) {
134	        failure_codes = errors.filter_map(error => {
135	          match field(error, "code") {
136	            Some(Json::String(code)) if code.length() > 0 &&
137	              code.length() <= 80 &&
138	              code.iter().all(c => (c >= 'a' && c <= 'z') || c == '_') =>
139	              Some(Json::string(code))
140	            _ => None
141	          }
142	        })
143	      }
144	      guard code == 0 else {
145	        raise AdapterError(
146	          "Remote activity probe failed (exit \{code}; errors " +
147	          Json::array(failure_codes).stringify() +
148	          ")",
149	        )
150	      }
151	      guard parsed is Some(value) else {
152	        raise AdapterError("Invalid activity JSON")
153	      }
154	      guard field(value, "schemaVersion") == Some(Json::number(1)) &&
155	        ["idle", "active", "unknown"].contains(required(value, "activity")) else {
156	        raise AdapterError("Invalid activity response")
157	      }
158	      value
159	    })
160	  })
161	}
