    recover_connection(state) catch {
      error => {
        set_field(result, "outcome", Json::string("failed"))
        set_field(
          result,
          "error",
          Json::string(
            diagnostic_error(error, environment=workspace_environment(state)),
          ),
        )
      }
    }

